const STORE='zerogaspil-ci-v1';
const CATEGORIES=['Baguette','Pain spécial','Croissant','Pain au chocolat','Viennoiserie','Brioche','Beignet','Cake et biscuit','Gâteau individuel','Tarte et dessert','Pâtisserie salée','Plat du jour','Riz et accompagnement','Attiéké et accompagnement','Poulet','Poisson','Viande','Pâtes','Sandwich','Burger','Pizza','Salade','Repas végétarien','Portion traiteur','Fruits','Légumes','Produits laitiers','Yaourt','Jus et boissons','Produits secs','Riz et céréales','Conserves','Snacks','Produits frais','Petit-déjeuner','Goûter','Panier mixte','Panier familial','Panier étudiant','Produits locaux','Autre'];
const TYPES=['Boulangerie','Pâtisserie','Restaurant','Traiteur','Épicerie','Supérette','Hôtel','Autre'];
const ICONS=['🥐','🍰','🍲','🥖','🧺','🥗','🍞','🍩','🥪','🍛'];
let db=load();let current='home',adminTab='overview',clientTab='offers',activeShopId=localStorage.getItem('zerogaspil-active-shop')||'',activeUserEmail=localStorage.getItem('zerogaspil-session')||'',selectedRole='Client',authMode='login',rolePickerOpen=false;
function load(){try{let d=JSON.parse(localStorage.getItem(STORE))||emptyDb();return {...emptyDb(),...d,products:d.products||[],messages:d.messages||[],reviews:d.reviews||[],favorites:d.favorites||[],notifications:d.notifications||[],waitlists:d.waitlists||[],coupons:d.coupons||[],issues:d.issues||[],donations:d.donations||[],settings:d.settings||{whatsapp:''}}}catch{return emptyDb()}}
function emptyDb(){return {users:[],shops:[],offers:[],reservations:[],activity:[],products:[],messages:[],reviews:[],favorites:[],notifications:[],waitlists:[],coupons:[],issues:[],donations:[],settings:{whatsapp:''}}}
function save(){localStorage.setItem(STORE,JSON.stringify(db));render()}
function esc(s=''){return String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
function money(n){return `${Number(n||0).toLocaleString('fr-FR')} FCFA`}
function dateNow(){return new Date().toLocaleString('fr-FR',{dateStyle:'short',timeStyle:'short'})}
function id(prefix){return prefix+'-'+Math.random().toString(36).slice(2,7).toUpperCase()}
function log(action,detail){db.activity.unshift({id:id('EVT'),action,detail,at:dateNow()});db.activity=db.activity.slice(0,100);if(action==='Commande créée'){notify('Administration','Nouvelle commande',detail);notify('Commerçant','Commande à préparer',detail)}else if(action==='Inscription')notify('Administration','Nouvelle inscription',detail);else if(action==='Retrait validé')notify('Client','Retrait confirmé',detail);else if(action==='Réservation annulée')notify('Commerçant','Commande annulée',detail)}
function notify(role,title,body,link=''){db.notifications.unshift({id:id('NTF'),role,title,body,link,at:dateNow(),read:false});db.notifications=db.notifications.slice(0,100)}
window.addEventListener('storage',e=>{if(e.key===STORE){db=load();render()}});
function nav(page){let rolePage={client:'Client',merchant:'Commerçant',agent:'Agent',admin:'Administrateur'};let u=activeUser();if(rolePage[page]&&(!u||u.role!==rolePage[page])){selectedRole=rolePage[page];authMode='login';current='auth';render();return}current=page;document.querySelectorAll('.nav-item').forEach(x=>x.classList.toggle('active',x.dataset.page===page));document.getElementById('sidebar').classList.remove('open');render();window.scrollTo({top:0,behavior:'smooth'})}
document.querySelectorAll('.nav-item').forEach(b=>b.addEventListener('click',()=>nav(b.dataset.page)));
document.getElementById('menuBtn').onclick=()=>document.getElementById('sidebar').classList.toggle('open');
document.getElementById('resetBtn').onclick=()=>{if(confirm('Supprimer toutes les informations saisies sur cet appareil ? Cette action est irréversible.')){db=emptyDb();activeUserEmail='';localStorage.removeItem(STORE);localStorage.removeItem('zerogaspil-session');localStorage.removeItem('zerogaspil-active-shop');render();toast('Les données ont été réinitialisées.')}};
document.querySelector('.avatar').onclick=()=>{if(activeUserEmail){if(confirm('Se déconnecter de ce compte ?')){activeUserEmail='';localStorage.removeItem('zerogaspil-session');nav('home')}}else openLogin()};
document.getElementById('closeModal').onclick=()=>document.getElementById('modal').close();
function toast(s){let t=document.getElementById('toast');t.textContent=s;t.classList.add('show');setTimeout(()=>t.classList.remove('show'),2600)}
function openModal(title,eyebrow,html,onSubmit){let m=document.getElementById('modal');document.getElementById('modalTitle').textContent=title;document.getElementById('modalEyebrow').textContent=eyebrow;document.getElementById('modalBody').innerHTML=html;m.showModal();let f=m.querySelector('form');if(f)f.onsubmit=e=>{e.preventDefault();const data=Object.fromEntries(new FormData(f).entries());if(onSubmit(data)!==false)m.close()}}
function field(label,name,opts={}){let req=opts.required?'required':'';let cls=opts.full?'form-field full':'form-field';let input;if(opts.options){input=`<select class="field" name="${name}" ${req}>${opts.options.map(x=>`<option value="${esc(x)}">${esc(x)}</option>`).join('')}</select>`}else if(opts.textarea){input=`<textarea class="field" name="${name}" rows="3" ${req} placeholder="${esc(opts.placeholder||'')}">${esc(opts.value||'')}</textarea>`}else{input=`<input class="field" name="${name}" type="${opts.type||'text'}" ${req} value="${esc(opts.value||'')}" placeholder="${esc(opts.placeholder||'')}">`}return `<div class="${cls}"><label>${label}${opts.required?' *':''}</label>${input}</div>`}
function formHtml(fields,submit='Enregistrer'){return `<form class="modal-form"><div class="form-grid">${fields}</div><div class="modal-actions"><button type="button" class="button secondary" onclick="document.getElementById('modal').close()">Annuler</button><button class="button">${submit} <span>→</span></button></div></form>`}
function empty(title,desc,action='',fn=''){return `<div class="empty-card fade-in"><div class="empty-illustration">✳</div><h3>${title}</h3><p>${desc}</p>${action?`<button class="button small" onclick="${fn}">＋ ${action}</button>`:''}</div>`}
function pageHead(eyebrow,title,desc,button='',fn=''){return `<div class="section-head"><div><div class="eyebrow">${eyebrow}</div><h2>${title}</h2><p>${desc}</p></div>${button?`<button class="button" onclick="${fn}">＋ ${button}</button>`:''}</div>`}
function metric(label,value,icon,note='Calculé avec vos données'){return `<div class="metric"><div class="metric-top">${label}<span class="metric-icon">${icon}</span></div><div class="metric-value">${value}</div><div class="metric-note">${note}</div></div>`}
function roleCard(icon,title,desc,page){return `<div class="role-card fade-in" onclick="nav('${page}')"><div class="role-icon">${icon}</div><h3>${title}</h3><p>${desc}</p><span class="role-link">Accéder à l’espace <b>→</b></span></div>`}
function home(){let booked=db.reservations.length;return `<section class="hero fade-in"><div class="hero-copy"><div class="eyebrow">MOINS DE GASPILLAGE, PLUS DE PARTAGE</div><h1>Les bons produits<br>trouvent leur place.</h1><p>Une plateforme locale pour valoriser les invendus alimentaires et rendre les bons repas plus accessibles.</p><button class="button" onclick="nav('client')">Découvrir les paniers <span>→</span></button></div><div class="hero-art"><span>♧</span></div></section>
${pageHead('VOTRE PLATEFORME','Un espace pour chacun','Choisissez votre espace pour commencer. Les informations sont ajoutées par votre équipe.')}
<div class="role-grid">${roleCard('◉','Espace client','Parcourir les offres, réserver un panier et suivre son retrait.','client')}${roleCard('▦','Espace commerçant','Créer votre commerce, publier des paniers et préparer les retraits.','merchant')}${roleCard('◈','Administration','Gérer la plateforme, les comptes, les offres et les réservations.','admin')}</div>
${pageHead('APERÇU','La plateforme en un coup d’œil','Les indicateurs se remplissent à mesure que vous ajoutez des données.')}
<div class="metrics">${metric('Commerces',db.shops.length,'⌂')}${metric('Paniers disponibles',db.offers.filter(o=>o.status==='Disponible'&&o.qty>0).length,'▧')}${metric('Réservations',booked,'◷')}${metric('Repas valorisés',db.reservations.filter(r=>r.status==='Retiré').reduce((a,r)=>a+Number(r.qty),0),'♡')}</div>
<div class="notice"><strong>À vous de renseigner les informations.</strong> Aucun commerce, produit, prix, compte ou réservation n’est préchargé. Les catégories proposées servent uniquement de choix dans les formulaires.</div>`}
function entryHome(){if(rolePickerOpen)return `<div class="entry-screen role-screen"><div class="entry-brand"><span class="brand-mark">Z</span><b>ZéroGaspil <em>CI</em></b></div><button class="auth-back" onclick="startEntry()">← Retour à l’assiette</button><div class="role-intro"><span class="eyebrow">CHOISISSEZ VOTRE ESPACE</span><h1>Qui êtes-vous ?</h1><p>Chaque rôle dispose de son espace et de ses outils dédiés.</p></div><div class="entry-role-grid"><button class="entry-role" onclick="chooseRole('Agent')"><span class="entry-role-icon">✦</span><b>Agent</b><small>Suivre retraits et opérations</small><i>→</i></button><button class="entry-role" onclick="chooseRole('Client')"><span class="entry-role-icon">◉</span><b>Client</b><small>Découvrir et commander</small><i>→</i></button><button class="entry-role" onclick="chooseRole('Commerçant')"><span class="entry-role-icon">▦</span><b>Commerçant</b><small>Publier produits et paniers</small><i>→</i></button><button class="entry-role" onclick="chooseRole('Administrateur')"><span class="entry-role-icon">◈</span><b>Administrateur</b><small>Gérer la plateforme</small><i>→</i></button></div><button class="entry-info-link" onclick="nav('info')">ⓘ Informations et aide</button></div>`;return `<div class="entry-screen landing-screen"><div class="entry-brand"><span class="brand-mark">Z</span><b>ZéroGaspil <em>CI</em></b><span class="entry-tag">SAUVER DES REPAS · PRÉSERVER SON BUDGET</span></div><main class="landing-center"><div class="landing-copy"><span class="eyebrow">LA BONNE NOUVELLE DU JOUR</span><h1>Un bon repas mérite<br>une seconde chance.</h1><p>Découvrez les offres alimentaires des commerces près de vous et aidez à réduire le gaspillage, un panier à la fois.</p></div><button class="plate-stage" onclick="openRoleSelector()" aria-label="Ouvrir l’assiette et choisir mon espace"><span class="plate-halo"></span><span class="plate-shadow"></span><span class="plate-rim"><span class="plate-inner"><i class="food food-one">🥐</i><i class="food food-two">🥖</i><i class="food food-three">🥗</i><i class="food food-four">🍓</i><i class="plate-leaf">✳</i></span></span><span class="plate-label">ZÉRO<br><b>GASPIL</b><small>Toucher pour commencer</small></span><span class="plate-spark spark-one">✦</span><span class="plate-spark spark-two">✧</span></button><button class="button entry-cta" onclick="openRoleSelector()">Ouvrir mon espace <span>→</span></button><div class="entry-foot"><span>Une plateforme locale anti-gaspillage</span><button onclick="nav('info')">Informations & aide</button></div></main><div class="landing-orbit orbit-a"></div><div class="landing-orbit orbit-b"></div></div>`}
function openRoleSelector(){let p=document.querySelector('.plate-stage');if(p)p.classList.add('opening');setTimeout(()=>{rolePickerOpen=true;current='home';render()},450)}
function backToRoles(){rolePickerOpen=true;current='home';render()}
function visitorOffer(o,i){let s=db.shops.find(x=>x.id===o.shopId);return `<article class="item-card fade-in"><div class="item-visual">${ICONS[i%ICONS.length]}<span class="pill">${esc(o.category)}</span></div><div class="item-info"><h3>${esc(o.name)}</h3><p>${esc(s?.name||o.shop)} · ${esc(s?.area||'')}<br>${esc(o.day)} · ${esc(o.slot)} · ${o.qty} disponible(s)</p><div class="item-foot"><span class="price">${money(o.price)}</span><button class="button small secondary" onclick="chooseRole('Client')">Voir pour commander</button></div></div></article>`}
function visitor(){let active=db.offers.filter(o=>o.status==='Disponible'&&o.qty>0&&!offerExpired(o));return `<section class="hero fade-in"><div class="hero-copy"><div class="eyebrow">ACCUEIL · DÉCOUVRIR SANS COMPTE</div><h1>Les bons produits<br>trouvent leur place.</h1><p>ZéroGaspil CI met en relation les commerces et les clients pour donner une seconde chance aux produits encore disponibles.</p><button class="button" onclick="openRoleSelector()">Choisir mon espace <span>→</span></button></div><div class="hero-art"><span>♧</span></div></section><div class="section-head"><div><div class="eyebrow">COMMENT ÇA MARCHE</div><h2>Simple, du commerce au retrait</h2><p>Parcourez cette présentation sans créer de compte.</p></div><button class="button secondary" onclick="nav('info')">Informations & aide</button></div><div class="role-grid"><article class="role-card"><div class="role-icon">01</div><h3>Le commerce publie</h3><p>Le commerçant saisit les produits ou paniers, les quantités, les prix et le créneau de retrait.</p></article><article class="role-card"><div class="role-icon">02</div><h3>Le client commande</h3><p>Il consulte les offres et ses coordonnées de contact sont jointes à la commande.</p></article><article class="role-card"><div class="role-icon">03</div><h3>Le retrait est confirmé</h3><p>Le client présente son code. Le commerçant le vérifie et l’administration voit l’évolution.</p></article></div><div class="section-head"><div><div class="eyebrow">OFFRES SAISIES PAR LES COMMERCES</div><h2>À découvrir</h2><p>Vous pouvez parcourir les offres sans vous connecter. La commande nécessite un compte.</p></div></div><div class="item-grid">${active.length?active.map(visitorOffer).join(''):empty('Aucune offre publiée','Les offres apparaîtront ici après leur saisie par un commerçant.')}</div><div class="section-head"><div><div class="eyebrow">VOTRE ESPACE</div><h2>Choisir un rôle</h2><p>La connexion et l’inscription sont propres à chaque rôle.</p></div></div><div class="entry-role-grid visitor-roles">${['Agent','Client','Commerçant','Administrateur'].map((r,i)=>`<button class="entry-role" onclick="chooseRole('${r}')"><span class="entry-role-icon">${['✦','◉','▦','◈'][i]}</span><b>${r}</b><small>${['Opérations et retraits','Découvrir et commander','Gérer les offres','Administrer la plateforme'][i]}</small><i>→</i></button>`).join('')}</div><div class="notice" style="margin-top:24px"><strong>Mode démonstration :</strong> aucune commande ou transaction réelle n’est effectuée. Les offres visibles sont celles saisies sur cet appareil.</div>`}
function agent(){let rows=db.reservations.slice().reverse();return `${pageHead('ESPACE AGENT','Suivi des retraits','Retrouvez les commandes à préparer, vérifiez les codes et consignez les retraits.') }<div class="notice"><strong>Accès agent :</strong> cet espace regroupe les opérations de retrait. Les paiements et les comptes restent simulés.</div>${rows.length?merchantReservations(rows):empty('Aucune commande à traiter','Les commandes apparaîtront ici dès qu’un client en passe une.')}`}
let infoAudience='Tout le monde';
const INFO_ITEMS=[
 {group:'Tout le monde',q:'Qu’est-ce que ZéroGaspil CI ?',a:'ZéroGaspil CI met en relation des commerces qui saisissent leurs produits disponibles et des clients qui souhaitent les acheter à prix réduit ou sous forme de panier.'},
 {group:'Tout le monde',q:'Les paiements sont-ils réels ?',a:'Non. Dans ce prototype, Wave, Orange Money, MTN Mobile Money et le paiement au retrait sont des options de démonstration. Aucune transaction n’est effectuée et aucun code secret de paiement ne doit être saisi.'},
 {group:'Tout le monde',q:'Pourquoi ne vois-je aucune offre au départ ?',a:'Le projet démarre sans données fictives. Un commerçant doit créer sa fiche et saisir lui-même ses produits ou paniers, prix, quantités et horaires.'},
 {group:'Tout le monde',q:'Quelles informations sont partagées lors d’une commande ?',a:'Le commerçant concerné et l’administration voient les coordonnées saisies pour la commande, son contenu, son créneau, son statut et son code de retrait. Ces informations servent à préparer et remettre la commande dans cette simulation.'},
 {group:'Tout le monde',q:'Comment contacter l’administration ?',a:'Utilisez le formulaire « Contacter l’administration ». La demande est conservée dans le prototype; WhatsApp s’ouvre si un numéro a été configuré dans l’espace Administration.'},
 {group:'Clients',q:'Puis-je acheter un seul produit ou un panier ?',a:'Oui. Les offres portant la mention « À l’unité » correspondent à un produit. Les paniers sont des offres groupées définies par le commerçant.'},
 {group:'Clients',q:'Comment réserver une offre ?',a:'Choisissez une offre, renseignez ou vérifiez vos coordonnées, indiquez la quantité et le moyen de paiement simulé, puis confirmez. Le stock diminue et la commande apparaît dans votre espace.'},
 {group:'Clients',q:'Comment se passe le retrait ?',a:'La confirmation fournit un code de retrait et, lorsque la bibliothèque QR est accessible, un QR code. Présentez le code au commerçant pendant le créneau indiqué. Le commerçant doit saisir le code exact pour confirmer le retrait.'},
 {group:'Clients',q:'Puis-je annuler ou signaler un problème ?',a:'Une commande au statut « Réservé » peut être annulée depuis votre liste. Le bouton « Signaler » permet d’envoyer un problème à l’administration. Les règles affichées ici sont celles du prototype.'},
 {group:'Clients',q:'Comment fonctionnent les points et le parrainage ?',a:'Dans la démonstration, un client connecté reçoit des points lorsque le commerçant confirme le retrait. Le code de parrainage peut être partagé lors d’une inscription; le bonus du parrain est simulé.'},
 {group:'Commerçants',q:'Comment enregistrer mon commerce ?',a:'Créez un compte commerçant, puis saisissez le nom du commerce, son type, son adresse, son quartier, son téléphone et les horaires. La fiche apparaît ensuite dans l’administration.'},
 {group:'Commerçants',q:'Comment publier un produit ou un panier ?',a:'Depuis votre espace, publiez un produit vendu à l’unité ou un panier composé. Renseignez le nom, la catégorie, la quantité, le prix et le créneau. Vous pouvez préciser une date limite, les articles et les allergènes connus.'},
 {group:'Commerçants',q:'Comment confirmer un retrait ?',a:'Dans la liste des commandes, vérifiez l’identité du client et saisissez le code de retrait fourni. Un code incorrect ne valide pas la commande. L’heure du retrait est ensuite enregistrée.'},
 {group:'Commerçants',q:'Que faire en cas d’absence du client ?',a:'Utilisez « Non présenté » pour enregistrer l’absence. Le stock n’est pas remis automatiquement en vente : le commerçant décide s’il peut encore proposer les articles.'},
 {group:'Commerçants',q:'Puis-je importer plusieurs offres ?',a:'Oui. L’import CSV accepte une ligne par produit avec les colonnes séparées par des points-virgules : Nom;Catégorie;Quantité;Prix;Date de retrait;Créneau.'},
 {group:'Commerçants',q:'Que signifie consigner un don ?',a:'Cette action enregistre la quantité restante comme donnée à une structure locale et l’ajoute au bilan de démonstration. Elle ne contacte pas une association réelle.'},
 {group:'Données & prototype',q:'Les informations sont-elles synchronisées entre appareils ?',a:'Non. Les données sont enregistrées dans le stockage local du navigateur. Les vues de la même application se mettent à jour, et des onglets du même navigateur peuvent se synchroniser, mais il n’y a pas de serveur commun.'},
 {group:'Données & prototype',q:'Puis-je utiliser un vrai mot de passe ou des données sensibles ?',a:'Non. Les comptes sont simulés et les mots de passe de démonstration restent sur l’appareil. N’utilisez pas de mot de passe réutilisé, de code Mobile Money ou d’information bancaire.'},
 {group:'Données & prototype',q:'Le QR code est-il toujours disponible ?',a:'Le code textuel de retrait reste la référence. Le QR code est généré si la bibliothèque externe peut être chargée; sans connexion, présentez le code textuel.'}
];
function setInfoAudience(a){infoAudience=a;renderInfo()}
function renderInfo(){let q=document.getElementById('infoSearch')?.value.toLowerCase()||'',items=INFO_ITEMS.filter(x=>(infoAudience==='Tout le monde'||x.group==='Tout le monde'||x.group===infoAudience)&&(`${x.q} ${x.a}`).toLowerCase().includes(q));let root=document.getElementById('infoContent');if(root)root.innerHTML=items.length?items.map((x,i)=>`<details class="faq-item" ${i===0?'open':''}><summary>${esc(x.q)}<span>＋</span></summary><p>${esc(x.a)}</p></details>`).join(''):empty('Aucun résultat','Essayez un autre mot-clé ou choisissez une autre rubrique.')}
function information(){return `${pageHead('CENTRE D’AIDE','Informations & aide','Les explications pratiques pour utiliser ZéroGaspil CI côté client ou côté commerce.')}<div class="info-banner"><div class="info-symbol">i</div><div><h2>Un repère pour chaque étape</h2><p>Consultez les réponses avant de commander, publier une offre ou confirmer un retrait.</p></div></div><div class="toolbar info-tools"><input id="infoSearch" class="field search" placeholder="Rechercher une information…" oninput="renderInfo()"><div class="category-chips">${['Tout le monde','Clients','Commerçants','Données & prototype'].map(x=>`<button class="category-chip ${infoAudience===x?'active':''}" onclick="setInfoAudience('${x}')">${x}</button>`).join('')}</div></div><div class="info-layout"><div class="info-menu"><b>Accès rapide</b><button onclick="nav('client')">Trouver une offre <span>→</span></button><button onclick="nav('merchant')">Espace commerçant <span>→</span></button><button onclick="openSupport()">Contacter l’administration <span>→</span></button></div><div id="infoContent" class="faq-list"></div></div><div class="notice info-foot"><strong>Prototype de simulation :</strong> les opérations, paiements et comptes ne sont pas réels. Les règles de production, les politiques d’annulation et les intégrations devront être définies avant le lancement commercial.</div>`}
function addAccount(role){openSignup(role)}
function openSignup(fixedRole=''){if(fixedRole)selectedRole=fixedRole;authMode='signup';current='auth';render()}
function openLogin(){if(!rolePickerOpen&&!activeUser())rolePickerOpen=true;authMode='login';if(!activeUser()&&!['Client','Commerçant','Agent','Administrateur'].includes(selectedRole))selectedRole='Client';current='auth';render()}
function startEntry(){rolePickerOpen=false;authMode='login';selectedRole='Client';current='home';render()}
function openRoleSelector(){rolePickerOpen=true;render()}
function chooseRole(role){selectedRole=role;authMode='login';current='auth';render()}
function setAuthMode(mode){authMode=mode;render()}
function logoutToLanding(){activeUserEmail='';localStorage.removeItem('zerogaspil-session');rolePickerOpen=false;current='home';render();window.scrollTo({top:0,behavior:'smooth'})}
function authPage(){let signup=authMode==='signup',fields=signup?field('Nom complet','name',{required:true})+field('Téléphone','phone',{required:true})+field('Adresse e-mail','email',{type:'email',required:true})+field('Adresse de résidence','address',{required:true,full:true})+field('Quartier / commune','area',{required:true})+field('Date de naissance','birthDate',{type:'date',required:true})+field('Code de parrainage (facultatif)','referral')+field('Mot de passe','password',{type:'password',required:true,full:true}):field('Adresse e-mail','email',{type:'email',required:true})+field('Mot de passe','password',{type:'password',required:true,full:true});return `<div class="auth-page"><button class="auth-back" onclick="backToRoles()">← Retour au choix des espaces</button><div class="auth-card"><div class="brand-mini"><span class="brand-mark">Z</span><b>ZéroGaspil CI</b></div><span class="eyebrow">ESPACE ${esc(selectedRole.toUpperCase())}</span><h1>${signup?'Créer votre compte':'Heureux de vous revoir'}</h1><p class="muted">${signup?'Renseignez vos informations pour accéder à votre espace.':'Connectez-vous pour ouvrir votre espace dédié.'}</p><div class="auth-tabs"><button class="${!signup?'active':''}" onclick="setAuthMode('login')">Se connecter</button><button class="${signup?'active':''}" onclick="setAuthMode('signup')">S’inscrire</button></div><form id="authForm"><div class="form-grid">${fields}</div><div class="auth-note">Prototype de simulation : les comptes et mots de passe sont stockés localement sur cet appareil. N’utilisez pas de vrai mot de passe.</div><button class="button auth-submit">${signup?'Créer mon compte':'Se connecter'} <span>→</span></button></form><button class="auth-switch-role" onclick="backToRoles()">Choisir un autre espace</button></div></div>`}
function submitAuth(e){e.preventDefault();let d=Object.fromEntries(new FormData(e.currentTarget).entries()),email=d.email.trim().toLowerCase();if(authMode==='signup'){if(db.users.some(u=>u.email===email)){toast('Cette adresse e-mail existe déjà.');return}let inviter=db.users.find(x=>x.referralCode===d.referral?.trim().toUpperCase());let u={id:id('USR'),...d,email,role:selectedRole,referralCode:id('AMI'),referrerId:inviter?.id||'',points:0,created:dateNow()};db.users.push(u);activeUserEmail=email;localStorage.setItem('zerogaspil-session',email);log('Inscription',`${u.name} · ${u.role}`);finishAuth(u)}else{let u=db.users.find(x=>x.email===email&&x.password===d.password);if(!u){toast('Compte introuvable ou mot de passe incorrect sur cet appareil.');return}if(u.role!==selectedRole){toast(`Ce compte est de type ${u.role}. Revenez au choix des espaces pour sélectionner le bon rôle.`);return}activeUserEmail=email;localStorage.setItem('zerogaspil-session',email);finishAuth(u)}}
function finishAuth(u){current={Client:'client',Commerçant:'merchant',Agent:'agent',Administrateur:'admin'}[u.role]||'home';rolePickerOpen=false;save();toast(`Bienvenue ${u.name} !`);window.scrollTo({top:0,behavior:'smooth'})}
function activeUser(){return db.users.find(u=>u.email===activeUserEmail)}
function editProfile(){let u=activeUser();if(!u){toast('Connectez-vous pour modifier votre profil.');openLogin();return}openModal('Modifier mon profil','INFORMATIONS PERSONNELLES',formHtml(field('Nom complet','name',{required:true,value:u.name})+field('Téléphone','phone',{required:true,value:u.phone})+field('E-mail','email',{type:'email',required:true,value:u.email})+field('Adresse','address',{required:true,value:u.address})+field('Quartier / commune','area',{required:true,value:u.area})+field('Date de naissance','birthDate',{type:'date',required:true,value:u.birthDate}), 'Enregistrer les modifications'),d=>{let other=db.users.find(x=>x.email===d.email.toLowerCase()&&x.id!==u.id);if(other){toast('Cette adresse e-mail est déjà utilisée.');return false}Object.assign(u,d,{email:d.email.toLowerCase()});activeUserEmail=u.email;localStorage.setItem('zerogaspil-session',u.email);log('Profil modifié',u.name);save();toast('Profil mis à jour.')})}
function openNotifications(){let relevant=db.notifications.filter(n=>n.role==='Tous'||n.role===(activeUser()?.role||'Visiteur')||n.role==='Administration');openModal('Centre de notifications',`${relevant.filter(n=>!n.read).length} NON LUE(S)`,relevant.length?`<div class="modal-form">${relevant.map(n=>`<div class="profile-line"><span class="profile-icon">${n.read?'✓':'●'}</span><div><b>${esc(n.title)}</b><small>${esc(n.body)}</small><small>${esc(n.at)}</small></div></div>`).join('')}<div class="modal-actions"><button class="button" onclick="markNotificationsRead()">Tout marquer comme lu</button></div></div>`:empty('Aucune alerte','Les nouvelles commandes et mises à jour apparaîtront ici.'),()=>true)}
function markNotificationsRead(){let visible=db.notifications.filter(n=>n.role==='Tous'||n.role===(activeUser()?.role||'Visiteur')||n.role==='Administration');visible.forEach(n=>n.read=true);document.getElementById('modal').close();save();toast('Notifications marquées comme lues.');openNotifications()}
function exportCsv(kind){let rows=kind==='orders'?db.reservations.map(r=>({Reference:r.id,Client:r.client,Telephone:r.phone,Email:r.email,Adresse:r.address,Commerce:r.shop,Offre:r.name,Quantite:r.qty,Total_FCFA:r.price,Code:r.code,Statut:r.status,Commande_le:r.created,Retire_le:r.pickedAt||'',Paiement:r.payment})):db.users.map(u=>({Nom:u.name,Role:u.role,Telephone:u.phone,Email:u.email,Adresse:u.address,Quartier:u.area,Naissance:u.birthDate,Inscription:u.created}));if(!rows.length){toast('Aucune donnée à exporter.');return}let keys=Object.keys(rows[0]),csv=[keys.join(';'),...rows.map(r=>keys.map(k=>`"${String(r[k]||'').replace(/"/g,'""')}"`).join(';'))].join('\r\n');let a=document.createElement('a');a.href=URL.createObjectURL(new Blob(['\ufeff'+csv],{type:'text/csv;charset=utf-8'}));a.download=`zerogaspil-${kind}-${new Date().toISOString().slice(0,10)}.csv`;a.click();URL.revokeObjectURL(a.href);toast('Export CSV téléchargé.')}
function addShop(){let u=activeUser();openModal('Enregistrer un commerce','NOUVEAU COMMERCE',formHtml(field('Nom du commerce','name',{required:true})+field('Type de commerce','type',{options:TYPES})+field('Téléphone','phone',{required:true,value:u?.phone})+field('E-mail de contact','email',{type:'email',value:u?.email})+field('Quartier / commune','area',{required:true,placeholder:'À renseigner',value:u?.area})+field('Adresse complète','address',{required:true,full:true, value:u?.address})+field('Horaires de retrait','hours',{required:true,placeholder:'Ex. 17 h – 19 h'})+field('Nom du responsable','manager',{required:true,value:u?.name})+field('Description','description',{textarea:true,full:true}), 'Enregistrer le commerce'),d=>{db.shops.push({id:id('COM'),...d,ownerId:u?.id||'',status:'À vérifier',created:dateNow()});log('Commerce ajouté',d.name);save();toast('Commerce enregistré.')})}
function merchantShops(){let u=activeUser();return u?.role==='Commerçant'?db.shops.filter(s=>s.ownerId===u.id):db.shops}
function notifyFollowers(shop,title){for(let uid of (shop.followers||[])){let person=db.users.find(u=>u.id===uid);if(person)notify('Client',`Nouvelle offre chez ${shop.name}`,title)}}
function addProduct(){let shops=merchantShops();if(!shops.length){toast('Créez d’abord un commerce.');return}let choices=[...shops].sort((a,b)=>a.id===activeShopId?-1:b.id===activeShopId?1:0).map(s=>s.name);openModal('Ajouter un produit à l’unité','NOUVEAU PRODUIT',formHtml(field('Commerce','shop',{options:choices,required:true})+field('Nom du produit','name',{required:true})+field('Catégorie','category',{options:CATEGORIES,required:true})+field('Quantité disponible','qty',{type:'number',required:true})+field('Prix unitaire (FCFA)','price',{type:'number',required:true})+field('Jour de retrait','day',{type:'date',required:true})+field('Créneau de retrait','slot',{required:true,placeholder:'Ex. 17 h – 19 h'})+field('À consommer avant (facultatif)','expiry',{type:'date'})+field('Description et allergènes','description',{textarea:true,full:true}), 'Publier le produit'),d=>{let q=Number(d.qty),p=Number(d.price);if(q<1||p<0){toast('Vérifiez la quantité et le prix.');return false}let s=shops.find(x=>x.name===d.shop);db.offers.push({id:id('PRD'),...d,shopId:s.id,kind:'Produit',qty:q,price:p,usual:0,items:d.name,status:'Disponible',created:dateNow()});log('Produit publié',`${d.name} · ${d.shop}`);notifyFollowers(s,d.name);save();toast('Produit disponible à l’unité.')})}
function addOffer(){let shops=merchantShops();if(!shops.length){toast('Ajoutez d’abord un commerce.');return}let choices=[...shops].sort((a,b)=>a.id===activeShopId?-1:b.id===activeShopId?1:0).map(s=>s.name);openModal('Créer un panier','NOUVELLE OFFRE',formHtml(field('Commerce','shop',{options:choices,required:true})+field('Nom du panier','name',{required:true,placeholder:'À saisir par le commerçant'})+field('Catégorie principale','category',{options:CATEGORIES,required:true})+field('Quantité disponible','qty',{type:'number',required:true})+field('Prix habituel indicatif (FCFA)','usual',{type:'number'})+field('Prix proposé (FCFA)','price',{type:'number',required:true})+field('Jour de retrait','day',{type:'date',required:true})+field('Créneau horaire','slot',{required:true,placeholder:'Ex. 17 h – 19 h'})+field('À consommer avant (facultatif)','expiry',{type:'date'})+field('Articles réellement inclus','items',{textarea:true,full:true,placeholder:'Saisissez les articles inclus dans ce panier'})+field('Description / allergènes','description',{textarea:true,full:true}), 'Publier le panier'),d=>{if(Number(d.qty)<1||Number(d.price)<0){toast('Vérifiez la quantité et le prix.');return false}let shop=shops.find(s=>s.name===d.shop);db.offers.push({id:id('PAN'),...d,shopId:shop.id,kind:'Panier',qty:Number(d.qty),usual:Number(d.usual||0),price:Number(d.price),status:'Disponible',created:dateNow()});log('Panier publié',`${d.name} · ${d.shop}`);notifyFollowers(shop,d.name);save();toast('Panier publié et visible dans le catalogue.')})}
function offerExpired(o){return !!(o.expiry&&o.expiry<new Date().toISOString().slice(0,10))}
function client(){let available=db.offers.filter(o=>o.status==='Disponible'&&Number(o.qty)>0&&!offerExpired(o));let u=activeUser();let mine=db.reservations.filter(r=>u?r.clientId===u.id:r.clientId==='guest');let saved=mine.reduce((n,r)=>n+Number(r.savings||0),0),rescued=mine.filter(r=>r.status==='Retiré').reduce((n,r)=>n+Number(r.qty),0),areas=[...new Set(db.shops.map(s=>s.area).filter(Boolean))];return `${pageHead('ESPACE CLIENT','Les offres près de vous','Achetez un produit seul ou choisissez un panier proposé par un commerce.','Créer un compte','addAccount(\'Client\')')}<div class="notice"><strong>Commande de démonstration :</strong> paiement simulé, code de retrait unique. Les informations saisies sont partagées avec le commerçant et l’administration pour organiser le retrait.</div><div class="metrics">${metric('Économies estimées',money(saved),'↘')}${metric('Portions retirées',rescued,'♡')}${metric('Points fidélité',u?.points||0,'★')}${metric('Commandes',mine.length,'◷')}</div>${u?.referralCode?`<div class="notice"><strong>Parrainage :</strong> partagez le code ${esc(u.referralCode)}. Vous gagnez des points après le premier retrait du filleul. <button class="button small secondary" onclick="copyReferral()">Copier</button></div>`:''}<div class="toolbar"><input class="field search" id="offerSearch" placeholder="Rechercher un produit, panier ou commerce…" oninput="filterOffers()"><select class="field filter" id="catFilter" onchange="filterOffers()"><option value="">Toutes les catégories</option>${CATEGORIES.map(c=>`<option>${esc(c)}</option>`).join('')}</select><select class="field filter" id="areaFilter" onchange="filterOffers()"><option value="">Tous les quartiers</option>${areas.map(c=>`<option>${esc(c)}</option>`).join('')}</select><select class="field filter" id="typeFilter" onchange="filterOffers()"><option value="">Tous les commerces</option>${TYPES.map(c=>`<option>${esc(c)}</option>`).join('')}</select><button class="button secondary small" onclick="toggleFavoritesView()">♡ Favoris</button><button class="button secondary small" onclick="editProfile()">Mon profil</button><button class="button secondary small" onclick="openSupport()">Contacter l’administration</button></div><div class="item-grid" id="offerGrid">${available.length?available.map((o,i)=>offerCard(o,i)).join(''):empty('Aucune offre disponible','Les produits et paniers apparaîtront ici après leur saisie par un commerçant.')}</div>${db.offers.filter(o=>o.qty===0||o.status==='Épuisé').length?`<div class="panel" style="margin-top:15px"><h3>Épuisé — recevoir une alerte</h3>${db.offers.filter(o=>o.qty===0||o.status==='Épuisé').map(o=>`<div class="profile-line"><span class="profile-icon">◷</span><div style="flex:1"><b>${esc(o.name)}</b><small>${esc(o.shop)} · rupture temporaire</small></div><button class="button small secondary" onclick="joinWaitlist('${o.id}')">M’alerter</button></div>`).join('')}</div>`:''}${pageHead('VOTRE ACTIVITÉ','Mes commandes','Retrouvez vos codes, le statut et l’heure de retrait.')}${mine.length?reservationTable(mine.slice().reverse()):empty('Aucune commande','Vos commandes s’afficheront ici après votre première réservation.')}`}
let onlyFavorites=false;
function offerCard(o,i){let shop=db.shops.find(s=>s.id===o.shopId),fav=db.favorites.includes(o.id),discount=o.usual>o.price?Math.round((o.usual-o.price)/o.usual*100):0;return `<article class="item-card fade-in"><div class="item-visual">${ICONS[i%ICONS.length]}<span class="pill">${esc(o.category)}</span><span class="pill" style="position:absolute;right:10px;top:12px">${o.kind==='Produit'?'À l’unité':'Panier'}</span>${discount?`<span class="discount-tag">−${discount}%</span>`:''}</div><div class="item-info"><h3>${esc(o.name)}</h3><p>${esc(shop?.name||o.shop)} · ${esc(shop?.area||'Quartier non renseigné')}<br>Retrait : ${esc(o.day)} · ${esc(o.slot)} · ${o.qty} disponible(s) ${o.qty<=3?'<span class="pill orange">Stock limité</span>':''}</p><div class="item-foot"><span class="price">${money(o.price)}${o.usual?`<small>${money(o.usual)}</small>`:''}</span><div class="action-row"><button class="icon-button" title="Ajouter aux favoris" onclick="toggleFavorite('${o.id}')">${fav?'♥':'♡'}</button><button class="button small secondary" onclick="showOffer('${o.id}')">Détails</button><button class="button small" onclick="reserve('${o.id}')">${o.kind==='Produit'?'Acheter':'Choisir'}</button></div></div></div></article>`}
function filterOffers(){let q=(document.getElementById('offerSearch')?.value||'').toLowerCase(),c=document.getElementById('catFilter')?.value||'',area=document.getElementById('areaFilter')?.value||'',type=document.getElementById('typeFilter')?.value||'';let list=db.offers.filter(o=>{let s=db.shops.find(x=>x.id===o.shopId);return o.status==='Disponible'&&o.qty>0&&!offerExpired(o)&&(o.name+' '+o.shop+' '+o.category+' '+o.items+' '+o.description).toLowerCase().includes(q)&&(!c||o.category===c)&&(!area||s?.area===area)&&(!type||s?.type===type)&&(!onlyFavorites||db.favorites.includes(o.id))});let grid=document.getElementById('offerGrid');if(grid)grid.innerHTML=list.length?list.map(offerCard).join(''):empty('Aucun résultat','Aucun article ne correspond aux filtres choisis.')}
function toggleFavorite(oid){let i=db.favorites.indexOf(oid);if(i>=0)db.favorites.splice(i,1);else db.favorites.push(oid);save();toast(i>=0?'Retiré des favoris.':'Ajouté aux favoris.')}
function toggleFavoritesView(){onlyFavorites=!onlyFavorites;filterOffers();toast(onlyFavorites?'Affichage des favoris.':'Affichage de toutes les offres.')}
function copyReferral(){let code=activeUser()?.referralCode;if(!code)return;navigator.clipboard?.writeText(code).then(()=>toast('Code de parrainage copié.')).catch(()=>toast(`Votre code : ${code}`))}
function showOffer(oid){let o=db.offers.find(x=>x.id===oid),s=o&&db.shops.find(x=>x.id===o.shopId);if(!o)return;let followed=activeUser()&&s?.followers?.includes(activeUser().id);openModal('Détails de l’offre','INFORMATIONS DU COMMERCE',`<div class="modal-form"><div class="notice"><strong>${esc(o.name)}</strong> · ${esc(o.kind||'Panier')}<br>Catégorie : ${esc(o.category)}<br>Articles : ${esc(o.items||o.name)}<br>Description et allergènes : ${esc(o.description||'Non renseigné')}<br>Prix : ${money(o.price)}${o.usual?` · prix habituel ${money(o.usual)}`:''}<br>Stock : ${o.qty}${o.expiry?`<br>À consommer avant : ${esc(o.expiry)}`:''}</div><div class="profile-line"><span class="profile-icon">⌂</span><div><b>${esc(s?.name||o.shop)} · ${esc(s?.type||'')}</b><small>${esc(s?.phone||'')} · ${esc(s?.email||'')}</small><small>${esc(s?.address||'')} · ${esc(s?.area||'')}</small><small>Horaires : ${esc(s?.hours||o.slot)} · Retrait : ${esc(o.day)} ${esc(o.slot)}</small><small>Avis : ${shopScore(o.shopId)}</small></div></div><div class="modal-actions"><button class="button secondary" onclick="toggleFollow('${o.shopId}')">${followed?'Ne plus suivre':'Suivre ce commerce'}</button><button class="button" onclick="document.getElementById('modal').close();reserve('${o.id}')">Continuer</button></div></div>`,()=>true)}
function shopScore(sid){let a=db.reviews.filter(v=>v.shopId===sid);return a.length?`${(a.reduce((n,v)=>n+v.score,0)/a.length).toFixed(1)}/10 (${a.length} avis)`:'Aucun avis'}
function toggleFollow(sid){let u=activeUser();if(!u){toast('Connectez-vous pour suivre un commerce.');openLogin();return}let s=db.shops.find(x=>x.id===sid);if(!s)return;s.followers=s.followers||[];let i=s.followers.indexOf(u.id);if(i>=0){s.followers.splice(i,1);toast('Vous ne suivez plus ce commerce.')}else{s.followers.push(u.id);toast('Commerce suivi. Vous recevrez ses nouvelles offres.')}save()}
function joinWaitlist(oid){let u=activeUser();if(!u){toast('Connectez-vous pour demander une alerte de stock.');openLogin();return}if(db.waitlists.some(w=>w.offerId===oid&&w.userId===u.id)){toast('Vous êtes déjà sur la liste d’attente.');return}db.waitlists.push({id:id('WAIT'),offerId:oid,userId:u.id,created:dateNow()});log('Alerte de disponibilité demandée',`${u.name} · ${oid}`);save();toast('Nous vous alerterons si le commerçant remet ce produit en stock.')}
function restockOffer(oid){let o=db.offers.find(x=>x.id===oid);if(!o)return;let q=Number(prompt('Nouvelle quantité à ajouter au stock :','1'));if(!Number.isFinite(q)||q<1)return;o.qty+=q;o.status='Disponible';let waiters=db.waitlists.filter(w=>w.offerId===oid);for(let w of waiters){let u=db.users.find(x=>x.id===w.userId);if(u)notify('Client',`Produit de nouveau disponible : ${o.name}`,`Nouvelle quantité : ${q}`)}db.waitlists=db.waitlists.filter(w=>w.offerId!==oid);log('Stock remis à jour',`${o.name} · +${q}`);save();toast('Stock actualisé; les clients en attente ont été alertés.')}
function reserve(offerId){let o=db.offers.find(x=>x.id===offerId);if(!o||o.qty<1)return;let shop=db.shops.find(s=>s.id===o.shopId),u=activeUser(),admin=adminContact();openModal(o.kind==='Produit'?'Commander ce produit':'Réserver ce panier','COMMANDE',formHtml(`<div class="form-field full"><div class="notice"><strong>${esc(o.name)}</strong> · ${o.kind==='Produit'?'produit à l’unité':'panier'}<br>${esc(shop?.name||o.shop)} · ${esc(shop?.phone||'')}<br>${esc(shop?.address||'Adresse à renseigner')}<br>Retrait : ${esc(o.day)} · ${esc(o.slot)}<br>${money(o.price)} l’unité · ${o.qty} disponible(s)</div></div>`+field('Nom du client','client',{required:true,value:u?.name})+field('Téléphone','phone',{required:true,value:u?.phone})+field('E-mail','email',{type:'email',required:true,value:u?.email})+field('Adresse du client','address',{required:true,full:true,value:u?.address})+field('Quantité','qty',{type:'number',required:true,value:'1'})+field('Code promo (facultatif)','promo')+field('Moyen de paiement simulé','payment',{options:['Wave (simulation)','Orange Money (simulation)','MTN Mobile Money (simulation)','Paiement au retrait'],required:true})+'<div class="form-field full auth-note">Le commerçant et l’administrateur verront votre nom, votre numéro et les détails du retrait.</div>', 'Confirmer la commande'),d=>{let q=Number(d.qty);if(q<1||q>o.qty){toast('La quantité demandée dépasse le stock disponible.');return false}let coupon=db.coupons.find(c=>c.code===d.promo?.trim().toUpperCase()&&c.active&&c.used<c.limit&&c.until>=new Date().toISOString().slice(0,10));if(d.promo&&!coupon){toast('Code promotionnel invalide ou épuisé.');return false}let subtotal=o.price*q,discount=coupon?Math.round(subtotal*coupon.percent/100):0,total=subtotal-discount,savings=Math.max(0,(Number(o.usual)||o.price)*q-total);let r={id:id('RES'),code:id('RET'),offerId:o.id,shopId:o.shopId,shop:shop?.name||o.shop,shopPhone:shop?.phone||'',shopEmail:shop?.email||'',shopAddress:shop?.address||'',adminName:admin.name,adminPhone:admin.phone,adminEmail:admin.email,adminWhatsApp:admin.whatsapp,name:o.name,kind:o.kind||'Panier',client:d.client,phone:d.phone,email:d.email,address:d.address,clientId:u?.id||'guest',qty:q,price:total,savings,couponDiscount:discount,coupon:coupon?.code||'',payment:d.payment,status:'Réservé',created:dateNow(),day:o.day,slot:o.slot,pickupAt:`${o.day} ${o.slot}`};o.qty-=q;if(o.qty===0)o.status='Épuisé';db.reservations.push(r);if(coupon)coupon.used++;log('Commande créée',`${r.client} · ${r.name} · ${r.code}`);save();toast('Commande créée. Code de retrait : '+r.code);setTimeout(()=>showReceipt(r),120)})}
function showReceipt(r){let body=`<div class="modal-form"><div class="qr-card"><div class="qr-box" id="qrCode"></div><div><div class="eyebrow">CODE DE RETRAIT</div><div class="qr-ref">${esc(r.code)}</div><p class="muted">Présentez ce QR code ou le code au commerçant lors du retrait.</p></div></div><div class="notice" style="margin-top:14px"><strong>${esc(r.name)}</strong><br>${esc(r.shop)} · ${esc(r.shopAddress)}<br>Téléphone commerce : ${esc(r.shopPhone||'À renseigner')} · ${esc(r.shopEmail||'')}<br>Administration : ${esc(r.adminName||'À configurer')} · ${esc(r.adminPhone||'À configurer')} · ${esc(r.adminEmail||'')}<br>Retrait : ${esc(r.day)} · ${esc(r.slot)}<br>Quantité : ${r.qty} · Total : ${money(r.price)}<br>Commande passée : ${esc(r.created)}</div><div class="modal-actions"><button class="button" onclick="document.getElementById('modal').close()">Terminé</button></div></div>`;openModal('Commande confirmée','GARDEZ CE CODE',body,()=>true);if(window.QRCode)new QRCode(document.getElementById('qrCode'),{text:r.code,width:100,height:100});else document.getElementById('qrCode').innerHTML=`<div style="font-size:10px;text-align:center">QR indisponible<br><b>${esc(r.code)}</b></div>`}
function reservationTable(rows){return `<div class="panel table-wrap"><table><thead><tr><th>Référence</th><th>Produit / commerce / contact</th><th>Client et contact</th><th>Retrait prévu / heure</th><th>Code</th><th>Paiement simulé</th><th>Administration</th><th>Statut</th><th>Action</th></tr></thead><tbody>${rows.map(r=>`<tr><td><b>${esc(r.id)}</b></td><td>${esc(r.name)}<br><b>${esc(r.shop)}</b><br>${esc(r.shopPhone||'')} · ${esc(r.shopEmail||'')}<br>${esc(r.shopAddress||'')}<br><span class="muted">${r.qty} × ${money(r.price/Math.max(1,r.qty))}${r.coupon?` · promo ${esc(r.coupon)}`:''}</span></td><td><b>${esc(r.client)}</b><br>${esc(r.phone||'')}<br>${esc(r.email||'')}<br>${esc(r.address||'')}</td><td>${esc(r.day)} · ${esc(r.slot)}<br>Commandé : ${esc(r.created)}${r.pickedAt?`<br>Retiré : ${esc(r.pickedAt)}`:''}</td><td><b>${esc(r.code)}</b></td><td>${esc(r.payment)}</td><td><b>${esc(r.adminName||'À configurer')}</b><br>${esc(r.adminPhone||'')}<br>${esc(r.adminEmail||'')}</td><td>${statusPill(r.status)}</td><td><div class="action-row">${r.status==='Réservé'?`<button class="button small secondary" onclick="cancelReservation('${r.id}')">Annuler</button><button class="button small secondary" onclick="setPickupReminder('${r.id}')">Rappel</button>`:''}${r.status==='Retiré'&&!r.review?`<button class="button small" onclick="openRating('${r.id}')">Noter /10</button>`:''}${!r.issueReported?`<button class="button small secondary" onclick="reportIssue('${r.id}')">Signaler</button>`:''}</div></td></tr>`).join('')}</tbody></table></div>`}
function statusPill(s){let cl=s==='Retiré'?'':s==='Annulé'||s==='Épuisé'?'red':s==='À vérifier'||s==='Réservé'?'orange':'gray';return `<span class="pill ${cl}">${esc(s)}</span>`}
function cancelReservation(rid){let r=db.reservations.find(x=>x.id===rid);if(!r||r.status!=='Réservé')return;if(!confirm('Annuler cette réservation ?'))return;r.status='Annulé';let o=db.offers.find(x=>x.id===r.offerId);if(o){o.qty+=r.qty;o.status='Disponible'}log('Réservation annulée',`${r.client} · ${r.code}`);save();toast('Réservation annulée et stock remis à jour.')}
function merchant(){let shops=merchantShops(),shop=shops.find(s=>s.id===activeShopId)||shops[0];if(shop)activeShopId=shop.id;let myOffers=shop?db.offers.filter(o=>o.shopId===shop.id):[],myRes=shop?db.reservations.filter(r=>r.shopId===shop.id):[],lowStock=myOffers.filter(o=>o.status==='Disponible'&&o.qty<=3);return `${pageHead('ESPACE COMMERÇANT','Gérez vos offres et retraits','Créez votre compte commerçant, enregistrez votre commerce et saisissez vos offres.','Créer un compte','addAccount(\'Commerçant\')')}<div class="metrics">${metric('Mes commerces',shops.length,'⌂')}${metric('Offres actives',myOffers.filter(o=>o.status==='Disponible').length,'▧')}${metric('Réservations',myRes.length,'◷')}${metric('Note moyenne',shop?shopScore(shop.id):'—','★')}</div>${shop?`<div class="notice"><strong>Avis clients :</strong> ${shopScore(shop.id)}. ${lowStock.length?`<br><strong>Stock bas :</strong> ${lowStock.map(o=>`${esc(o.name)} (${o.qty} restants)`).join(' · ')}`:'Aucune alerte de stock bas.'}</div>`:''}${shops.length>1?`<div class="toolbar"><label class="muted">Commerce actif</label><select class="field filter" onchange="setShop(this.value)">${shops.map(s=>`<option value="${s.id}" ${s.id===shop?.id?'selected':''}>${esc(s.name)}</option>`).join('')}</select></div>`:''}
${pageHead('1 — VOTRE COMMERCE','Informations du commerce','Saisissez les coordonnées qui seront affichées aux clients.','Ajouter un commerce','addShop()')}${shops.length?`<div class="panel">${shops.map(s=>`<div class="profile-line"><span class="profile-icon">⌂</span><div style="flex:1"><b>${esc(s.name)} <span class="pill orange">${esc(s.status)}</span></b><small>${esc(s.type)} · ${esc(s.area)} · ${esc(s.phone)} · ${esc(s.hours)}</small><small>${esc(s.address)} · Responsable : ${esc(s.manager)}</small></div></div>`).join('')}</div>`:empty('Aucun commerce enregistré','Ajoutez les coordonnées de votre boulangerie, restaurant ou magasin pour commencer.','Enregistrer mon commerce','addShop()')}
${pageHead('2 — VOS OFFRES','Produits et paniers','Publiez un produit à l’unité ou un panier composé.','Créer un panier','addOffer()')}<div class="toolbar"><button class="button secondary small" onclick="addProduct()">＋ Ajouter un produit à l’unité</button><button class="button secondary small" onclick="importOffers()">Importer par CSV</button><button class="button secondary small" onclick="donateAvailable()">Consigner un don</button></div>${shops.length?myOffers.length?`<div class="item-grid">${myOffers.map(offerCard).join('')}</div>`:empty('Aucune offre publiée','Publiez un produit seul ou un panier composé.','Créer le premier panier','addOffer()'):''}
${myOffers.filter(o=>o.status==='Épuisé'||o.qty===0).length?`<div class="panel">${myOffers.filter(o=>o.status==='Épuisé'||o.qty===0).map(o=>`<div class="profile-line"><div style="flex:1"><b>${esc(o.name)} · Épuisé</b></div><button class="button small secondary" onclick="restockOffer('${o.id}')">Remettre en stock</button></div>`).join('')}</div>`:''}${pageHead('3 — À PRÉPARER','Réservations reçues','Le code client est partagé ici dès qu’une réservation est effectuée.')}${myRes.length?merchantReservations(myRes):empty('Aucune réservation','Les réservations liées à votre commerce apparaîtront ici.')}${pageHead('4 — AVIS','Évaluations des clients','Notes sur 10 après retrait confirmé.')}${db.reviews.filter(v=>shops.some(s=>s.id===v.shopId)).length?`<div class="panel">${db.reviews.filter(v=>shops.some(s=>s.id===v.shopId)).map(v=>`<div class="profile-line"><span class="profile-icon">★</span><div><b>${esc(v.shop)} · ${v.score}/10</b><small>${esc(v.client)} · ${esc(v.created)}</small><small>${esc(v.comment||'Aucun commentaire')}</small></div></div>`).join('')}</div>`:empty('Aucun avis pour le moment','Les évaluations apparaîtront après les premiers retraits.')}`}
function merchantReservations(rows){return `<div class="panel table-wrap"><table><thead><tr><th>Client et coordonnées</th><th>Commande</th><th>Créneau / horodatage</th><th>Code de retrait</th><th>Administration</th><th>Paiement simulé</th><th>Statut</th><th>Action</th></tr></thead><tbody>${rows.map(r=>`<tr><td><b>${esc(r.client)}</b><br>${esc(r.phone)}<br>${esc(r.email)}<br>${esc(r.address)}</td><td>${esc(r.name)} × ${r.qty}<br>${money(r.price)}</td><td>${esc(r.day)} · ${esc(r.slot)}<br>Commandé ${esc(r.created)}${r.pickedAt?`<br>Retiré ${esc(r.pickedAt)}`:''}</td><td><b>${esc(r.code)}</b></td><td><b>${esc(r.adminName||'Administration')}</b><br>${esc(r.adminPhone||'À configurer')}<br>${esc(r.adminEmail||'')}</td><td>${esc(r.payment)}</td><td>${statusPill(r.status)}</td><td><div class="action-row">${r.status==='Réservé'?`<button class="button small" onclick="markPicked('${r.id}')">Valider le retrait</button><button class="button small danger" onclick="markNoShow('${r.id}')">Non présenté</button>`:''}</div></td></tr>`).join('')}</tbody></table></div>`}
function markPicked(rid){let r=db.reservations.find(x=>x.id===rid);if(!r||r.status!=='Réservé')return;let code=prompt(`Saisissez le code communiqué par ${r.client} pour confirmer le retrait :`);if(code===null)return;if(code.trim().toUpperCase()!==r.code){toast('Code incorrect. Le retrait n’a pas été validé.');return}r.status='Retiré';r.pickedAt=dateNow();let u=db.users.find(x=>x.id===r.clientId);if(u&&!r.rewarded){u.points=(u.points||0)+10;r.rewarded=true;let inviter=db.users.find(x=>x.id===u.referrerId);if(inviter)inviter.points=(inviter.points||0)+5}log('Retrait validé',`${r.client} · ${r.code} · ${r.pickedAt}`);save();toast('Code vérifié. Retrait confirmé. 10 points de fidélité crédités au client.')}
function markNoShow(rid){let r=db.reservations.find(x=>x.id===rid);if(!r||r.status!=='Réservé')return;if(!confirm(`Confirmer que ${r.client} ne s’est pas présenté ? Le stock ne sera pas remis en vente automatiquement.`))return;r.status='Non retiré';r.noShowAt=dateNow();log('Client absent',`${r.client} · ${r.code}`);notify('Administration','Retrait manqué',`${r.client} · ${r.shop} · ${r.name}`);save();toast('Absence consignée. Le commerçant peut décider quoi faire du produit.')}
function recordDonation(oid){let o=db.offers.find(x=>x.id===oid);if(!o||!o.qty)return;let q=o.qty;if(!confirm(`Consigner ${q} unité(s) restante(s) comme données à une association ou structure locale ?`))return;db.donations.push({id:id('DON'),offerId:o.id,shopId:o.shopId,shop:o.shop,name:o.name,qty:q,at:dateNow()});o.qty=0;o.status='Donné';log('Don alimentaire consigné',`${q} × ${o.name} · ${o.shop}`);save();toast('Don consigné dans le bilan anti-gaspillage.')}
function donateAvailable(){let a=db.offers.filter(o=>merchantShops().some(s=>s.id===o.shopId)&&o.qty>0&&o.status==='Disponible');if(!a.length){toast('Aucun invendu disponible à consigner.');return}let answer=prompt('Choisissez le numéro de l’offre à donner :\n'+a.map((o,i)=>`${i+1}. ${o.name} — ${o.qty} restant(s)`).join('\n'));let n=Number(answer);if(n>=1&&n<=a.length)recordDonation(a[n-1].id)}
function importOffers(){let shops=merchantShops();let s=shops.find(x=>x.id===activeShopId)||shops[0];if(!s){toast('Ajoutez un commerce avant l’import.');return}openModal('Importer plusieurs offres','IMPORT RAPIDE CSV',formHtml(field('Lignes à importer','rows',{textarea:true,required:true,full:true,placeholder:'Une ligne par produit : Nom;Catégorie;Quantité;Prix FCFA;AAAA-MM-JJ;Créneau'} )+`<div class="form-field full auth-note">Utilisez le point-virgule entre les colonnes. Les catégories doivent correspondre au catalogue. Les données seront vérifiées avant import.</div>`,'Importer'),d=>{let valid=[],errors=[];d.rows.split(/\r?\n/).filter(x=>x.trim()).forEach((line,i)=>{let [name,category,qty,price,day,slot]=line.split(';').map(x=>x.trim());if(!name||!CATEGORIES.includes(category)||Number(qty)<1||Number(price)<0||!day||!slot)errors.push(i+1);else valid.push({id:id('PRD'),name,category,qty:Number(qty),price:Number(price),day,slot,shop:s.name,shopId:s.id,kind:'Produit',items:name,status:'Disponible',created:dateNow()})});if(errors.length){toast(`Import arrêté : vérifiez les lignes ${errors.join(', ')}.`);return false}db.offers.push(...valid);valid.forEach(x=>notifyFollowers(s,x.name));log('Import d’offres',`${valid.length} ligne(s) · ${s.name}`);save();toast(`${valid.length} offre(s) importée(s).`)})}
function reportIssue(rid){let r=db.reservations.find(x=>x.id===rid);if(!r)return;openModal('Signaler un problème','ASSISTANCE COMMANDE',formHtml(field('Motif','reason',{options:['Produit non conforme','Problème de retrait','Commerce fermé','Problème de paiement simulé','Autre']})+field('Détail','detail',{textarea:true,required:true,full:true}), 'Envoyer le signalement'),d=>{db.issues.push({id:id('INC'),reservationId:r.id,shop:r.shop,client:r.client,phone:r.phone,reason:d.reason,detail:d.detail,created:dateNow(),status:'À traiter'});log('Incident signalé',`${r.id} · ${d.reason}`);notify('Administration','Nouveau signalement',`${r.client} · ${d.reason}`);save();toast('Signalement transmis à l’administration.')})}
function setPickupReminder(rid){let r=db.reservations.find(x=>x.id===rid);if(!r)return;let hm=r.slot.match(/(\d{1,2})\s*(?:h|:)(\d{2})?/i);let target=new Date(`${r.day}T${String(hm?Number(hm[1]):12).padStart(2,'0')}:${String(hm&&hm[2]?Number(hm[2]):0).padStart(2,'0')}:00`);target.setMinutes(target.getMinutes()-30);db.notifications.unshift({id:id('NTF'),role:'Client',title:'Rappel de retrait programmé',body:`${r.name} chez ${r.shop} · ${r.day} ${r.slot}`,at:dateNow(),targetAt:target.toISOString(),read:false});save();toast('Rappel ajouté au centre de notifications.')}
function checkReminders(){let now=Date.now(),changed=false;for(let n of db.notifications){if(n.targetAt&&!n.fired&&new Date(n.targetAt).getTime()<=now){n.fired=true;n.read=false;n.title='Rappel : retrait à effectuer';changed=true}}if(changed)localStorage.setItem(STORE,JSON.stringify(db))}
function openRating(rid){let r=db.reservations.find(x=>x.id===rid);if(!r||r.status!=='Retiré')return;openModal('Noter le commerçant','VOTRE AVIS',formHtml(field('Note sur 10','score',{type:'number',required:true,value:'10'})+field('Votre commentaire','comment',{textarea:true,full:true}), 'Envoyer la note'),d=>{let n=Number(d.score);if(n<1||n>10){toast('Choisissez une note entre 1 et 10.');return false}r.review=n;db.reviews.push({id:id('REV'),reservationId:r.id,shopId:r.shopId,shop:r.shop,client:r.client,score:n,comment:d.comment,created:dateNow()});log('Avis publié',`${r.shop} · ${n}/10`);save();toast('Merci pour votre avis.')})}
function openSupport(){let u=activeUser();openModal('Écrire à l’administration','ASSISTANCE ZÉROGASPIL',formHtml(field('Nom complet','name',{required:true,value:u?.name})+field('Téléphone','phone',{required:true,value:u?.phone})+field('E-mail','email',{type:'email',required:true,value:u?.email})+field('Objet','subject',{required:true})+field('Votre question','body',{textarea:true,required:true,full:true})+`<div class="form-field full auth-note">Votre demande est enregistrée dans la démonstration et WhatsApp s’ouvrira si un numéro administrateur a été configuré.</div>`,'Continuer vers WhatsApp'),d=>{let m={id:id('MSG'),...d,created:dateNow(),userId:u?.id||''};db.messages.push(m);log('Demande de support',`${m.name} · ${m.subject}`);save();let phone=(db.settings.whatsapp||'').replace(/\D/g,'');if(phone){let url='https://wa.me/'+phone+'?text='+encodeURIComponent(`Bonjour, je suis ${m.name} (${m.phone}). ${m.subject} : ${m.body}`);window.open(url,'_blank','noopener')}else toast('Demande enregistrée. Configurez le WhatsApp administrateur pour ouvrir la conversation.')})}
function adminContact(){return {name:db.settings.adminName||'Administration ZéroGaspil CI',phone:db.settings.adminPhone||'',email:db.settings.adminEmail||'',whatsapp:db.settings.whatsapp||''}}
function setWhatsApp(){let c=adminContact();openModal('Coordonnées de l’administration','INFORMATIONS DE CONTACT',formHtml(field('Nom affiché','adminName',{required:true,value:c.name})+field('Téléphone','adminPhone',{required:true,value:c.phone,placeholder:'Indicatif pays inclus'})+field('Adresse e-mail','adminEmail',{type:'email',value:c.email})+field('Numéro WhatsApp','whatsapp',{value:c.whatsapp,placeholder:'Ex. 2250700000000'})+`<div class="form-field full auth-note">Ces coordonnées seront visibles dans les commandes côté client et commerçant. Le numéro WhatsApp sert aussi au formulaire de contact.</div>`,'Enregistrer les coordonnées'),d=>{db.settings.adminName=d.adminName;db.settings.adminPhone=d.adminPhone;db.settings.adminEmail=d.adminEmail;db.settings.whatsapp=d.whatsapp.replace(/\D/g,'');log('Coordonnées administrateur modifiées',d.adminName);save();toast('Coordonnées enregistrées et visibles sur les prochaines commandes.')})}
function createCoupon(){openModal('Créer un code promotionnel','OFFRE CLIENT',formHtml(field('Code à saisir','code',{required:true,placeholder:'EX. BIENVENUE'})+field('Réduction (%)','percent',{type:'number',required:true})+field('Nombre maximum d’utilisations','limit',{type:'number',required:true})+field('Date de fin','until',{type:'date',required:true}), 'Créer le code'),d=>{let p=Number(d.percent),limit=Number(d.limit),code=d.code.trim().toUpperCase();if(p<1||p>50||limit<1||db.coupons.some(c=>c.code===code)){toast('Code déjà utilisé ou paramètres invalides (réduction 1–50 %).');return false}db.coupons.push({id:id('CPN'),code,percent:p,limit,used:0,until:d.until,active:true});log('Code promo créé',code);save();toast('Code promotionnel activé.')})}
function admin(){let offers=db.offers,res=db.reservations;let categories=[...new Set(offers.map(o=>o.category))].map(cat=>({cat,n:res.filter(r=>db.offers.find(x=>x.id===r.offerId)?.category===cat).reduce((a,r)=>a+Number(r.qty),0)})).sort((a,b)=>b.n-a.n);return `${pageHead('ADMINISTRATION','Vue d’ensemble','Comptes, commerces et commandes saisis par les utilisateurs.','Créer un compte','addAccount(\'Administrateur\')')}<div class="metrics">${metric('Comptes',db.users.length,'♙')}${metric('Commerces',db.shops.length,'⌂')}${metric('Offres',offers.length,'▧')}${metric('Commandes',res.length,'◷')}</div>
<div class="toolbar">${['overview','users','shops','offers','reservations','reviews','categories','coupons','issues','donations','messages','activity'].map(t=>`<button class="category-chip ${adminTab===t?'active':''}" onclick="adminTab='${t}';render()">${({overview:'Vue d’ensemble',users:'Comptes',shops:'Commerces',offers:'Offres',reservations:'Commandes',reviews:'Avis',categories:'Catégories',coupons:'Promotions',issues:'Signalements',donations:'Dons alimentaires',messages:'Demandes WhatsApp',activity:'Journal'})[t]}</button>`).join('')}<button class="button secondary small" onclick="setWhatsApp()">⚙ WhatsApp</button><button class="button secondary small" onclick="exportCsv('orders')">↓ Exporter commandes</button><button class="button secondary small" onclick="exportCsv('users')">↓ Exporter comptes</button></div>${adminContent(categories)}`}
function adminContent(categories){if(adminTab==='overview'){let statusCounts=['Réservé','Retiré','Annulé'].map(s=>[s,db.reservations.filter(r=>r.status===s).length]);return `<div class="layout-two"><div class="panel"><div class="panel-title"><div><h3>Activité des réservations</h3><p>Volume par statut à partir des données actuelles</p></div></div>${db.reservations.length?`<div class="chart-bars">${statusCounts.map(([s,n])=>`<div class="chart-column"><b>${n}</b><div class="bar" style="height:${Math.max(5,n/Math.max(1,db.reservations.length)*100)}%"></div><small>${s}</small></div>`).join('')}</div><div class="chart-legend">Chaque barre représente le nombre de réservations observées.</div>`:empty('Pas encore de données','Les graphiques apparaîtront après les premières réservations.')}</div><div class="panel"><div class="panel-title"><div><h3>Catégories les plus proposées</h3><p>Basé sur les paniers saisis</p></div></div>${categories.length?categories.slice(0,6).map(c=>`<div class="profile-line"><span class="profile-icon">◌</span><div style="flex:1"><b>${esc(c.cat)}</b><small>${c.n} article(s) restant(s)</small></div></div>`).join(''):empty('Aucune catégorie utilisée','Les catégories se renseignent lors de la création des paniers.')}</div></div><div class="section-head"><div><div class="eyebrow">MISE À JOUR CONTINUE</div><h2>Dernières réservations</h2></div></div>${db.reservations.length?reservationTable(db.reservations.slice().reverse().slice(0,5)):empty('Aucune réservation','Les réservations des clients apparaîtront ici dès leur création.')}`}
if(adminTab==='users')return `${pageHead('ADMINISTRATION','Comptes utilisateurs','Coordonnées saisies lors de l’inscription.','Créer un compte','addAccount(\'Administrateur\')')}${db.users.length?`<div class="panel table-wrap"><table><thead><tr><th>Nom / rôle</th><th>Contact</th><th>Adresse et quartier</th><th>Date de naissance</th><th>Inscription</th><th>Action</th></tr></thead><tbody>${db.users.map(u=>`<tr><td><b>${esc(u.name)}</b><br>${statusPill(u.role)}</td><td>${esc(u.phone)}<br>${esc(u.email)}</td><td>${esc(u.address)}<br>${esc(u.area)}</td><td>${esc(u.birthDate)}</td><td>${esc(u.created)}</td><td><button class="button small danger" onclick="deleteEntity('users','${u.id}')">Supprimer</button></td></tr>`).join('')}</tbody></table></div>`:empty('Aucun compte','Les informations des inscriptions apparaîtront ici.','Créer un compte','addAccount(\'Administrateur\')')}`;
if(adminTab==='shops')return `${pageHead('ADMINISTRATION','Commerces','Coordonnées, horaires et validation des commerces.','Ajouter un commerce','addShop()')}${db.shops.length?`<div class="panel table-wrap"><table><thead><tr><th>Commerce</th><th>Type</th><th>Contact</th><th>Localisation</th><th>Horaires</th><th>Statut</th><th>Actions</th></tr></thead><tbody>${db.shops.map(s=>`<tr><td><b>${esc(s.name)}</b><br>${esc(s.manager)}</td><td>${esc(s.type)}</td><td>${esc(s.phone)}<br>${esc(s.email)}</td><td>${esc(s.area)}<br>${esc(s.address)}</td><td>${esc(s.hours)}</td><td>${statusPill(s.status)}</td><td><div class="action-row"><button class="button small secondary" onclick="approveShop('${s.id}')">Valider</button><button class="button small danger" onclick="deleteEntity('shops','${s.id}')">Supprimer</button></div></td></tr>`).join('')}</tbody></table></div>`:empty('Aucun commerce','Les commerces saisis par l’équipe apparaîtront dans cette liste.','Ajouter un commerce','addShop()')}`;
if(adminTab==='offers')return `${pageHead('ADMINISTRATION','Paniers publiés','Consultez et suivez les offres des commerces.','Créer un panier','addOffer()')}${offers.length?`<div class="panel table-wrap"><table><thead><tr><th>Panier</th><th>Commerce</th><th>Catégorie</th><th>Prix</th><th>Stock</th><th>Retrait</th><th>État</th><th></th></tr></thead><tbody>${offers.map(o=>`<tr><td><b>${esc(o.name)}</b><br>${esc(o.items)}</td><td>${esc(o.shop)}</td><td>${esc(o.category)}</td><td>${money(o.price)}</td><td>${o.qty}</td><td>${esc(o.day)}<br>${esc(o.slot)}</td><td>${statusPill(o.status)}</td><td><button class="button small danger" onclick="deleteEntity('offers','${o.id}')">Supprimer</button></td></tr>`).join('')}</tbody></table></div>`:empty('Aucun panier','Les paniers créés par les commerçants apparaîtront ici.','Créer un panier','addOffer()')}`;
if(adminTab==='reservations')return `${pageHead('ADMINISTRATION','Commandes et retraits','Client, coordonnées, produit, code, créneau et heures de commande/retrait.')}${res.length?reservationTable(res.slice().reverse()):empty('Aucune commande','Les commandes seront visibles ici dès leur création.')}`;
if(adminTab==='messages')return `${pageHead('ADMINISTRATION','Demandes des clients','Les demandes sont consignées ici et peuvent être transmises vers WhatsApp.')}${db.messages.length?`<div class="panel table-wrap"><table><thead><tr><th>Client</th><th>Contact</th><th>Objet et message</th><th>Reçu le</th></tr></thead><tbody>${db.messages.slice().reverse().map(m=>`<tr><td><b>${esc(m.name)}</b></td><td>${esc(m.phone)}<br>${esc(m.email)}</td><td><b>${esc(m.subject)}</b><br>${esc(m.body)}</td><td>${esc(m.created)}</td></tr>`).join('')}</tbody></table></div>`:empty('Aucune demande','Les demandes de contact apparaîtront ici.')}`;
if(adminTab==='coupons')return `${pageHead('ADMINISTRATION','Codes promotionnels','Créez des promotions simulées, limitées en pourcentage et en nombre d’utilisations.','Créer une promotion','createCoupon()')}${db.coupons.length?`<div class="panel table-wrap"><table><thead><tr><th>Code</th><th>Réduction</th><th>Utilisations</th><th>Expire le</th><th>Statut</th></tr></thead><tbody>${db.coupons.map(c=>`<tr><td><b>${esc(c.code)}</b></td><td>${c.percent}%</td><td>${c.used} / ${c.limit}</td><td>${esc(c.until)}</td><td>${statusPill(c.active&&c.used<c.limit&&c.until>=new Date().toISOString().slice(0,10)?'Actif':'Épuisé')}</td></tr>`).join('')}</tbody></table></div>`:empty('Aucun code promo','Les clients pourront saisir un code lorsqu’une promotion sera créée.')}`;
if(adminTab==='issues')return `${pageHead('ADMINISTRATION','Signalements et qualité','Suivez les problèmes concernant les commandes.')}${db.issues.length?`<div class="panel table-wrap"><table><thead><tr><th>Commande</th><th>Client</th><th>Contact</th><th>Commerce</th><th>Motif</th><th>Détail</th><th>Reçu le</th><th>Statut</th></tr></thead><tbody>${db.issues.map(x=>`<tr><td>${esc(x.reservationId)}</td><td>${esc(x.client)}</td><td>${esc(x.phone)}</td><td>${esc(x.shop)}</td><td>${esc(x.reason)}</td><td>${esc(x.detail)}</td><td>${esc(x.created)}</td><td>${statusPill(x.status)}</td></tr>`).join('')}</tbody></table></div>`:empty('Aucun signalement','Les problèmes signalés par les clients apparaîtront ici.')}`;
if(adminTab==='donations')return `${pageHead('IMPACT LOCAL','Dons et invendus','Tracez les quantités restantes données à des associations ou structures locales.')}${db.donations.length?`<div class="panel table-wrap"><table><thead><tr><th>Commerce</th><th>Produit</th><th>Quantité donnée</th><th>Date</th></tr></thead><tbody>${db.donations.map(d=>`<tr><td>${esc(d.shop)}</td><td>${esc(d.name)}</td><td>${d.qty}</td><td>${esc(d.at)}</td></tr>`).join('')}</tbody></table></div>`:empty('Aucun don consigné','Les commerçants peuvent enregistrer les invendus donnés en fin de journée.')}`;
if(adminTab==='reviews')return `${pageHead('ADMINISTRATION','Avis clients','Notes sur 10 et commentaires transmis après un retrait.')}${db.reviews.length?`<div class="panel table-wrap"><table><thead><tr><th>Commerce</th><th>Note</th><th>Client</th><th>Commentaire</th><th>Date</th></tr></thead><tbody>${db.reviews.slice().reverse().map(v=>`<tr><td><b>${esc(v.shop)}</b></td><td><span class="pill">${v.score}/10</span></td><td>${esc(v.client)}</td><td>${esc(v.comment)}</td><td>${esc(v.created)}</td></tr>`).join('')}</tbody></table></div>`:empty('Aucun avis','Les notes apparaîtront après les premiers retraits.')}`;
if(adminTab==='categories')return `${pageHead('CATALOGUE','Catégories proposées','Les catégories facilitent la saisie. Elles ne précréent aucun produit ni panier.') }<div class="panel"><div class="category-chips">${CATEGORIES.map(c=>`<span class="category-chip">${esc(c)}</span>`).join('')}</div><p class="muted" style="font-size:10px;margin-top:18px">Le catalogue est fourni comme liste de choix de départ. Il pourra être modifié dans le projet complet.</p></div>`;
return `${pageHead('ADMINISTRATION','Journal des actions','Historique des créations et changements effectués.')}${db.activity.length?`<div class="panel table-wrap"><table><thead><tr><th>Action</th><th>Détail</th><th>Date et heure</th></tr></thead><tbody>${db.activity.map(a=>`<tr><td>${esc(a.action)}</td><td>${esc(a.detail)}</td><td>${esc(a.at)}</td></tr>`).join('')}</tbody></table></div>`:empty('Aucune activité','Les actions réalisées seront consignées ici.')}`}
function approveShop(sid){let s=db.shops.find(x=>x.id===sid);if(s){s.status='Validé';log('Commerce validé',s.name);save();toast('Commerce validé.')}}
function setShop(sid){activeShopId=sid;localStorage.setItem('zerogaspil-active-shop',sid);render()}
function deleteEntity(kind,eid){if(!confirm('Supprimer cet élément ?'))return;db[kind]=db[kind].filter(x=>x.id!==eid);log('Élément supprimé',`${kind} · ${eid}`);save();toast('Élément supprimé.')}
function render(){checkReminders();let u=activeUser();if(current==='home'&&u&&!rolePickerOpen)current={Client:'client',Commerçant:'merchant',Agent:'agent',Administrateur:'admin'}[u.role]||'home';let names={home:'Accueil',visitor:'Accueil & découverte',auth:'Connexion / inscription',client:'Espace client',merchant:'Espace commerçant',agent:'Espace agent',admin:'Administration',info:'Informations & aide'};document.getElementById('pageTitle').textContent=names[current];let avatar=document.querySelector('.avatar'),count=document.getElementById('alertCount'),shell=document.querySelector('.app-shell');if(shell){shell.classList.toggle('landing',current==='home');shell.classList.toggle('flow',current==='auth')}if(avatar){avatar.textContent=u?u.name.split(/\s+/).map(x=>x[0]).join('').slice(0,2).toUpperCase():'ZG';avatar.title=u?`${u.name} · ${u.role}`:'Profil de démonstration'}document.getElementById('loginTop').style.display=u?'none':'';document.getElementById('signupTop').style.display=u?'none':'';document.getElementById('profileTop').style.display=u?'':'none';document.getElementById('switchTop').style.display=u?'':'none';document.querySelectorAll('.nav-item').forEach(n=>{let p=n.dataset.page,access={client:'Client',merchant:'Commerçant',agent:'Agent',admin:'Administrateur'}[p];n.style.display=p==='info'||p==='visitor'||(u&&access===u.role)?'':'none';n.classList.toggle('active',p===current)});if(count){let unread=db.notifications.filter(n=>!n.read&&(n.role==='Tous'||n.role===u?.role||n.role==='Administration')).length;count.textContent=unread?`(${unread})`:''}let pages={home:entryHome,visitor,auth:authPage,client,merchant,agent,admin,info:information};document.getElementById('content').innerHTML=`<div class="fade-in">${pages[current]()}</div>`;if(current==='info')renderInfo();if(current==='auth'){let f=document.getElementById('authForm');if(f)f.onsubmit=submitAuth}if(current==='home'){let foot=document.querySelector('.entry-foot');if(foot){let b=document.createElement('button');b.className='public-entry-link';b.textContent='Voir l’accueil sans compte';b.onclick=()=>nav('visitor');foot.prepend(b)}}}
render();
